from threading import Thread
from robot.utils.robottime import timestr_to_secs

from ute_common_admin.exception import AdminApiProcedureTimeoutException

from .base import BaseInterface
from ..validators import IsInstance, IsString


class AsyncTask(object):

    def __init__(self, inst, name, *args, **kwargs):
        self.name = "AsyncTask: {} args={} kwargs={}".format(name, args, kwargs)
        self.worker = Thread(target=self._execute_in_thread, args=(self._get_target_func(inst, name), args, kwargs))
        self.logger = self._get_logger(inst, kwargs)
        self.finished = False

    def __str__(self):
        return self.name

    def start(self):
        """Start worker thread."""
        self.logger.enable_buffering()
        self.finished = False
        self.worker.start()

    def collect_result(self, timeout):
        """Collect result."""
        self.worker.join(timeout)
        self.logger.flush()
        self.logger.disable_buffering()
        if not self.finished:
            raise AdminApiProcedureTimeoutException("{} not finished within timeout: {}".format(self.name, timeout))
        if isinstance(self.result, Exception):
            raise self.result  # pylint: disable-msg=E0702
        return self.result

    def _execute_in_thread(self, func, args, kwargs):
        try:
            self.result = func(*args, **kwargs)
        except Exception as e:
            self.result = e
        finally:
            self.finished = True
            self.logger.disable_buffering()

    def _get_target_func(self, inst, name):
        return getattr(inst, name.strip().lower().replace(" ", "_"))

    def _get_logger(self, inst, kwargs):
        alias = kwargs.get("alias", "default")
        return inst.store.get(alias).logger


class AsyncInterface(BaseInterface):

    def run_keyword_in_background(self, name, *args, **kwargs):
        """Run keyword in backgroud.

        :param string name: ute_admin keyword name.
        :rtype: AsyncTask
        :return: task object - executed keyword thread wrapper.
        :note: Experimental keyword.

        **WARNING!** Library ute_admin in not thread-safe.
        To avoid race condition do not execute other ute_admin keywords (with same alias) while running one in background.
        If necessary, please set up separate instance (alias).
        """
        IsString().check(name)
        task = AsyncTask(self, name, *args, **kwargs)
        task.start()
        return task

    def collect_keyword_result(self, task, timeout=120):
        """Collect keyword result.

        :param AsyncTask task: task object - executed keyword thread wrapper.
        :return: Keyword result.
        :raises: Keyword execution error.
        :note: Experimental keyword.
        """
        timeout = timestr_to_secs(timeout)
        IsInstance(AsyncTask).check(task)

        return task.collect_result(timeout)
